code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            minr = min(y for y, x in comp)
            maxr = max(y for y, x in comp)
            minc = min(x for y, x in comp)
            maxc = max(x for y, x in comp)
            cells = {(y - minr, x - minc) for y, x in comp}
            if (maxr - minr, maxc - minc) == (1, 2) and len(cells) == 4:
                # Stem above the three-cell bar maps to 3; stem below maps to 1.
                if {(0, 1), (1, 0), (1, 1), (1, 2)} == cells:
                    up += 1
                elif {(0, 0), (0, 1), (0, 2), (1, 1)} == cells:
                    down += 1
                else:
                    raise ValueError("Unexpected 4-cell component")
            else:
                raise ValueError("Unexpected component shape")
    out = [[0] * 6 for _ in range(3)]
    slots = ((0, 0), (2, 0), (0, 2), (2, 2))
    for i in range(up):
        r, c = slots[i]
        out[r][c] = 3
    for i in range(down):
        r, c = slots[i]
        out[r][c + 3] = 1
    return out
'''
